css:
.litigation-sim-container {
    padding: 24px;
    background: #f4f6f8;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.litigation-sim-header {
    background: linear-gradient(135deg, #0f1d3d 0%, #1a2744 100%);
    color: #f4f6f8;
    padding: 28px 32px;
    border-radius: 4px;
    margin-bottom: 20px;
    border-left: 6px solid #b8956a;
}
.litigation-sim-case-tag {
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #b8956a;
    margin-bottom: 8px;
    font-weight: 600;
}
.litigation-sim-header h1 {
    font-size: 1.6rem;
    font-weight: 600;
    margin: 0 0 6px 0;
    letter-spacing: -0.01em;
    color: #ffffff;
}
.litigation-sim-subtitle {
    font-size: 0.88rem;
    color: #c5cdd9;
    font-weight: 400;
    line-height: 1.5;
}
.litigation-sim-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: white;
    border-left: 4px solid #1a2744;
    padding: 14px 20px;
    margin-bottom: 20px;
    font-size: 0.95rem;
    box-shadow: 0 1px 2px rgba(15,29,61,0.05);
}
.litigation-sim-phase {
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-size: 0.78rem;
    font-weight: 700;
    color: #b8956a;
}
.litigation-sim-period {
    font-weight: 500;
    color: #1a2744;
    font-size: 0.9rem;
}
.litigation-sim-period span {
    margin: 0 2px;
}
.litigation-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 14px;
    margin-bottom: 20px;
}
.litigation-sim-kpi-card {
    background: white;
    padding: 20px 22px;
    box-shadow: 0 1px 3px rgba(15,29,61,0.08);
    border-top: 3px solid #1a2744;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.litigation-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(15,29,61,0.12);
}
.litigation-sim-kpi-cost { border-top-color: #c0392b; }
.litigation-sim-kpi-doctrine { border-top-color: #1a2744; }
.litigation-sim-kpi-narrative { border-top-color: #b8956a; }
.litigation-sim-kpi-trust { border-top-color: #2e7d5b; }
.litigation-sim-kpi-label {
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #5b6474;
    margin-bottom: 8px;
    font-weight: 700;
}
.litigation-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 4px;
    line-height: 1.1;
}
.litigation-sim-kpi-cost .litigation-sim-kpi-value { color: #c0392b; }
.litigation-sim-kpi-narrative .litigation-sim-kpi-value { color: #7a6142; }
.litigation-sim-kpi-trust .litigation-sim-kpi-value { color: #2e7d5b; }
.litigation-sim-kpi-sub {
    font-size: 0.74rem;
    color: #5f6878;
    font-style: italic;
    line-height: 1.4;
}
.litigation-sim-briefing {
    background: white;
    padding: 22px 26px;
    border-left: 4px solid #b8956a;
    margin-bottom: 20px;
    box-shadow: 0 1px 3px rgba(15,29,61,0.06);
}
.litigation-sim-briefing-tag {
    font-size: 0.72rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #b8956a;
    font-weight: 700;
    margin-bottom: 8px;
}
.litigation-sim-briefing h3 {
    font-size: 1.18rem;
    font-weight: 600;
    margin: 0 0 10px 0;
    color: #1a2744;
    line-height: 1.3;
}
.litigation-sim-briefing p {
    margin: 0;
    font-size: 0.95rem;
    line-height: 1.65;
    color: #3d4655;
}
.litigation-sim-controls {
    background: white;
    padding: 24px 26px;
    margin-bottom: 20px;
    border: 1px solid #d8dde6;
    border-top: 3px solid #1a2744;
}
.litigation-sim-controls h3 {
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #1a2744;
    margin-bottom: 16px;
}
.litigation-sim-controls label {
    display: block;
    font-size: 0.92rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 10px;
}
.litigation-sim-controls select {
    background: #ffffff;
    border: 1px solid #c5cdd9;
    color: #1a2744;
    padding: 11px 14px;
    border-radius: 3px;
    width: 100%;
    font-size: 0.92rem;
    margin-bottom: 12px;
    font-family: inherit;
}
.litigation-sim-controls select:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 3px rgba(26,39,68,0.1);
}
.litigation-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
    padding: 8px;
}
.litigation-sim-controls input[type="number"],
.litigation-sim-controls input[type="text"] {
    background: #ffffff;
    border: 1px solid #c5cdd9;
    color: #1a2744;
    padding: 11px 14px;
    border-radius: 3px;
    width: 100%;
    font-size: 0.92rem;
    font-family: inherit;
}
.litigation-sim-feedback {
    background: #f9f7f3;
    border-left: 3px solid #b8956a;
    padding: 12px 16px;
    font-size: 0.85rem;
    color: #5a4d36;
    line-height: 1.55;
    margin-bottom: 16px;
    min-height: 0;
    display: none;
}
.litigation-sim-feedback.visible {
    display: block;
}
.litigation-sim-buttons {
    display: flex;
    gap: 10px;
    align-items: center;
    flex-wrap: wrap;
}
.litigation-sim-buttons .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    font-weight: 600;
    letter-spacing: 0.04em;
    padding: 11px 26px;
    border-radius: 3px;
    font-size: 0.92rem;
}
.litigation-sim-buttons .btn-primary:hover,
.litigation-sim-buttons .btn-primary:focus {
    background: #0f1d3d;
    border-color: #0f1d3d;
    box-shadow: 0 2px 8px rgba(15,29,61,0.25);
}
.litigation-sim-buttons .btn-outline-secondary {
    border-color: #c5cdd9;
    color: #5b6474;
    font-weight: 500;
    padding: 9px 18px;
    font-size: 0.85rem;
    border-radius: 3px;
}
.litigation-sim-buttons .btn-outline-secondary:hover {
    background: #f4f6f8;
    color: #1a2744;
    border-color: #1a2744;
}
.litigation-sim-history {
    background: white;
    padding: 22px 26px;
    margin-bottom: 20px;
    border: 1px solid #d8dde6;
}
.litigation-sim-history h3 {
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #1a2744;
    margin-bottom: 14px;
}
.litigation-sim-history table {
    font-size: 0.86rem;
    color: #1a2744;
    margin-bottom: 0;
}
.litigation-sim-history thead th {
    background: #1a2744;
    color: #f4f6f8;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    font-size: 0.7rem;
    padding: 10px 12px;
    border: none;
}
.litigation-sim-history tbody td {
    padding: 10px 12px;
    border-bottom: 1px solid #e8ecf2;
    border-top: none;
}
.litigation-sim-history tbody tr:nth-child(even) {
    background: #fafbfc;
}
.litigation-sim-chart-wrapper {
    background: white;
    padding: 22px 26px;
    margin-bottom: 20px;
    border: 1px solid #d8dde6;
}
.litigation-sim-chart-wrapper h3 {
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #1a2744;
    margin-bottom: 14px;
}
.litigation-sim-chart-wrapper canvas {
    max-height: 320px !important;
}
@media (max-width: 768px) {
    .litigation-sim-container { padding: 14px; }
    .litigation-sim-header { padding: 22px; }
    .litigation-sim-header h1 { font-size: 1.25rem; }
    .litigation-sim-kpi-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
    .litigation-sim-kpi-value { font-size: 1.5rem; }
    .litigation-sim-buttons { flex-direction: column; align-items: stretch; }
    .litigation-sim-buttons .btn-primary,
    .litigation-sim-buttons .btn-outline-secondary { width: 100%; }
    .litigation-sim-period-bar { flex-direction: column; align-items: flex-start; gap: 6px; }
}

.litigation-sim-complete-notice { background:#eef2f8; border-left:4px solid #1a2744; color:#2b3446; padding:14px 18px; border-radius:3px; font-size:0.9rem; margin-top:12px; }
.litigation-sim-container :focus-visible,
.litigation-sim-container button:focus-visible,
.litigation-sim-container select:focus-visible,
.litigation-sim-container input:focus-visible { outline:3px solid #1a2744; outline-offset:2px; }
@media (prefers-reduced-motion: reduce) {
  .litigation-sim-container *, .litigation-sim-container *::before, .litigation-sim-container *::after {
    animation-duration:0.001ms !important; animation-iteration-count:1 !important;
    transition-duration:0.001ms !important; scroll-behavior:auto !important; }
}

