            // Platform score: the getPerformanceSummary composite (doctrine plus narrative plus trust minus 8 x cost, over 280, clamped 0 to 100) on the current values.
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: this._composite(newDoctrinal + newNarrative + newTrust - (newCost * 8)) });

            var idx = Math.min(state.currentPeriod - 1, this.PERIODS.length - 1);
            var period = this.PERIODS[idx];
            var fbEl = document.getElementById('decisionFeedback');
            if (fbEl && d.feedbackKey) {
                fbEl.innerHTML = window.mySimulation.t(d.feedbackKey);
                fbEl.classList.add('visible');
            }

            var self = this;
            setTimeout(function() {
                // __eqilPeriod is captured before submitPeriod increments state.currentPeriod.
                // Reading the live value advanced two periods, so the option list and briefing on
                // screen belonged to a later period than the one the validator was grading.
                // decisions is left undefined so the select falls back to its own first option
                // rather than being forced back to a on every render.
                self._populateSelect({ currentPeriod: __eqilPeriod + 1 });
                self._updateBriefing({ currentPeriod: __eqilPeriod + 1 });
            }, 400);

            return {
                period: state.currentPeriod,
                phase: window.mySimulation.t(period.phaseKey),
                choice: d.choice,
                optionLabel: window.mySimulation.t(d.optionLabelKey),
                doctrinalDelta: doctrinalDelta,
                narrativeDelta: narrativeDelta,
                trustDelta: trustDelta,
                costDelta: costDelta,
                doctrinalScore: newDoctrinal,
                narrativeScore: newNarrative,
                trustScore: newTrust,
                expectedCost: newCost
            };
        }

