        _performanceKey(rawComposite, doctrine, cost) {
            if (rawComposite >= 220 && doctrine >= 75 && cost <= 4) return 'excellent';
            if (rawComposite >= 160 && doctrine >= 60 && cost <= 6) return 'good';
            if (rawComposite >= 110) return 'developing';
            return 'beginner';
        }

        _composite(rawComposite) {
            // The authored composite is doctrine + narrative + trust - 8 x cost, which ranges from
            // negative to roughly 280. The reporting layer reads a 0-100 field, so the raw figure is
            // normalised here and kept separately as rawComposite for the band thresholds.
            return Math.max(0, Math.min(100, Math.round((rawComposite / 280) * 100)));
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var t = this._t.bind(this);
            var last = history[history.length - 1].results || {};
            var doctrine = Number(last.doctrinalScore) || 0;
            var narrative = Number(last.narrativeScore) || 0;
            var trust = Number(last.trustScore) || 0;
            var cost = last.expectedCost != null ? Number(last.expectedCost) : 12;

            var rawComposite = doctrine + narrative + trust - (cost * 8);
            var performance = this._performanceKey(rawComposite, doctrine, cost);
            var composite = this._composite(rawComposite);

            return {
                doctrinalScore: Math.round(doctrine),
                narrativeScore: Math.round(narrative),
                trustScore: Math.round(trust),
                expectedCostUsdM: Math.round(cost * 10) / 10,
                rawComposite: Math.round(rawComposite),
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: performance,
                performanceKey: performance,
                performanceLabel: t('perf_' + performance),
                insights: [t('insight_' + performance)]
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || this.getPerformanceSummary(
                (window.mySimulation && window.mySimulation.state && window.mySimulation.state.history) || []);
            var t = this._t.bind(this);
            if (!s || typeof s.overallScore !== 'number') return t('run_complete_brief');
            var lines = [];
            lines.push('<strong>' + t('perf_' + (s.performanceKey || 'beginner')) + '</strong>');
            lines.push(t('summary_score') + ': ' + s.overallScore + '/100');
            lines.push(t('kpi_doctrine') + ': ' + s.doctrinalScore + ' &middot; '
                + t('kpi_narrative') + ': ' + s.narrativeScore + ' &middot; '
                + t('kpi_trust') + ': ' + s.trustScore + ' &middot; '
                + t('kpi_cost') + ': $' + s.expectedCostUsdM + 'M');
            lines.push(t('verdict_' + (s.performanceKey || 'beginner')));
            if (s.insights && s.insights.length) lines.push('<em>' + s.insights.join(' ') + '</em>');
            return lines.join('<br>');
        }

